style.css:
@-moz-document domain("app.gohighlevel.com") {
/* Main background */
#app {
    background-color: #FAF9FF !important;
}

/* Primary buttons */
button.btn-primary {
    background-color: #7568E8 !important;
    border-color: #7568E8 !important;
    color: #FFFFFF !important;
}

/* Hover effect */
#sidebar-v2 a:hover {
    background-color: #E4DEFF !important;
}

/* Selected navigation */
#sidebar-v2 a.active {
    background-color: #E4DEFF !important;
    color: #5D50C7 !important;
}
}
